START = "<!-- lit_enrich:start -->"
END = "<!-- lit_enrich:end -->"
HEADING = "## LLM 二次加工"
RELIABILITY = "已做带原文定位的 LLM 二次加工；仍须人工复核"
MAX_SUMMARY = 4000
MAX_TEXT = 2000
MAX_QUOTE = 8000
MAX_CLAIMS = 100
MAX_ITEMS = 50


class EnrichError(Exception):
    pass


class UsageError(Exception):
    pass


class ArgumentParser(argparse.ArgumentParser):
    def error(self, message):
        raise UsageError(message)


def _within(path, root):
    try:
        return os.path.commonpath([os.path.realpath(path),
                                   os.path.realpath(root)]) == os.path.realpath(root)
    except (OSError, ValueError):
        return False


def _relative_parts(value, label):
    if not isinstance(value, str) or not value.strip():
        raise EnrichError(f"{label} 必须是非空路径字符串")
    value = value.strip().replace("\\", "/")
    if (value.startswith("/") or value.startswith("//") or
            re.match(r"^[A-Za-z]:", value) or os.path.isabs(value)):
        raise EnrichError(f"{label} 必须是相对库根的路径：{value}")
    parts = value.split("/")
    if any(p in ("", ".", "..") for p in parts):
        raise EnrichError(f"{label} 含空段、`.` 或 `..`，拒绝路径穿越：{value}")
    return value, parts


def resolve_markdown(value, vault):
    rel, _parts = _relative_parts(value, "evidence.path")
    if not rel.lower().endswith(".md"):
        raise EnrichError(f"证据路径必须是 markdown：{rel}")
    path = os.path.realpath(os.path.join(vault, *rel.split("/")))
    if not _within(path, vault):
        raise EnrichError(f"证据路径逃出库根：{rel}")
    if not os.path.isfile(path):
        raise EnrichError(f"证据 markdown 不存在：{rel}")
    return os.path.relpath(path, os.path.realpath(vault)).replace("\\", "/"), path


def load_page(value, vault):
    rel, parts = _relative_parts(value, "page")
    if rel.startswith("wiki/"):
        rel = rel[5:]
        parts = parts[1:]
    if not parts or parts[0] != "sources" or len(parts) < 2:
        raise EnrichError(f"page 必须指向 wiki/sources 下的 source 页：{value}")
    if not rel.lower().endswith(".md"):
        raise EnrichError(f"page 必须是 markdown：{value}")
    source_root = os.path.join(vault, "wiki", "sources")
    path = os.path.realpath(os.path.join(vault, "wiki", *rel.split("/")))
    if not _within(path, source_root):
        raise EnrichError(f"page 逃出 wiki/sources：{value}")
    if not os.path.isfile(path):
        raise EnrichError(f"wiki source 页不存在：sources/{'/'.join(parts[1:])}")
    text = K.read_text(path)
    fm_raw, body = K.split_frontmatter(text)
    fm = K.parse_frontmatter(fm_raw)
    if not fm_raw.strip() or fm.get("type") != "source":
        raise EnrichError(f"page 不是具有可读 type: source frontmatter 的 wiki source：{rel}")
    canonical = os.path.relpath(path, os.path.join(os.path.realpath(vault), "wiki"))
    canonical = canonical.replace("\\", "/")
    return {"page": canonical, "path": path, "text": text,
            "fm_raw": fm_raw, "fm": fm, "body": body}


def _as_list(value):
    if value in (None, ""):
        return []
    return value if isinstance(value, list) else [value]


def _tag_list(value):
    """tags 可能是 list，也可能是历史页面的 `a, b` 逗号标量。

    只做 tags 专用拆分：`sources` 等字段的逗号语义不同，不能共用。
    """
    if value in (None, ""):
        return []
    if isinstance(value, str):
        return [x.strip() for x in value.split(",") if x.strip()]
    return [str(x) for x in value]


def _walk_strings(obj):
    if isinstance(obj, str):
        yield obj
    elif isinstance(obj, dict):
        for value in obj.values():
            yield from _walk_strings(value)
    elif isinstance(obj, list):
        for value in obj:
            yield from _walk_strings(value)


def _reject_markers(clean):
    """拒绝 proposal 携带 lit_enrich 标记本身。

    否则 claim/quote/summary 里的 `<!-- lit_enrich:start -->` 会被原样写入，
    造成标记重复；下一次 apply 会因 starts != ends or starts > 1 永久拒绝覆盖。
    """
    for value in _walk_strings(clean):
        if START in value or END in value:
            raise EnrichError(
                "proposal 含 lit_enrich 标记文本，拒绝写入（会破坏幂等标记段）")


def raw_documents(page, vault):
    docs, warnings = [], []
    seen = set()
    for item in _as_list(page["fm"].get("sources")):
        for match in re.finditer(r"\[\[([^\]]+)\]\]", str(item)):
            target = match.group(1).split("|", 1)[0].split("#", 1)[0].strip()
            target = target.replace("\\", "/")
            if not target.startswith("raw/") or not target.lower().endswith(".md"):
                continue
            try:
                rel, path = resolve_markdown(target, vault)
                if rel in seen:
                    continue
                seen.add(rel)
                content = K.read_text(path)
                docs.append({"path": rel, "line_start": 1,
                             "line_end": len(content.split("\n")), "content": content})
            except EnrichError as exc:
                warnings.append(str(exc))
    return docs, warnings


def output_schema(page):
    text_list = {"type": "array", "maxItems": MAX_ITEMS,
                 "items": {"type": "string", "minLength": 1, "maxLength": MAX_TEXT}}
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "type": "object",
        "required": ["page", "summary", "claims"],
        "properties": {
            "page": {"const": page},
            "summary": {"type": "string", "minLength": 1, "maxLength": MAX_SUMMARY},
            "claims": {
                "type": "array", "minItems": 1, "maxItems": MAX_CLAIMS,
                "items": {
                    "type": "object", "required": ["text", "evidence"],
                    "properties": {
                        "text": {"type": "string", "minLength": 1, "maxLength": MAX_TEXT},
                        "evidence": {
                            "type": "object",
                            "required": ["path", "line_start", "line_end", "quote"],
                            "properties": {
                                "path": {"type": "string",
                                         "description": "库内已存在 markdown 的相对路径"},
                                "line_start": {"type": "integer", "minimum": 1},
                                "line_end": {"type": "integer", "minimum": 1},
                                "quote": {"type": "string", "minLength": 1,
                                          "maxLength": MAX_QUOTE},
                            },
                        },
                    },
                },
            },
            "limitations": text_list,
            "critical_assessment": text_list,
            "tags": {"type": "array", "maxItems": MAX_ITEMS,
                     "items": {"type": "string", "minLength": 1, "maxLength": 100}},
            "links": {"type": "array", "maxItems": MAX_ITEMS,
                      "items": {"type": "string", "minLength": 1, "maxLength": 500}},
        },
    }


def build_request(page_value, vault=None):
    vault = os.path.realpath(vault or K.VAULT)
    page = load_page(page_value, vault)
    raw, warnings = raw_documents(page, vault)
    result = {
        "schema": "lit_enrich.request.v1",
        "page": page["page"],
        "raw": raw,
        "existing_card": {"frontmatter": page["fm"], "body": page["body"]},
        "instructions": [
            "只返回一个 JSON 对象，不要 Markdown 围栏或额外解释。",
            "page 必须与请求完全一致；summary 非空；claims 至少一条。",
            "每条 claim 必须含 text 与 evidence(path,line_start,line_end,quote)。",
            "evidence 行号为 1-based 闭区间；quote 必须在指定行范围内逐字存在，不得改写空白。",
            "没有可逐字核验的证据就不要提出该 claim。",
            "limitations、critical_assessment、tags、links 可选，均须为字符串数组。",
        ],
        "output_contract": {"format": "single_json_object",
                            "schema": output_schema(page["page"])},
    }
    if warnings:
        result["warnings"] = warnings
    return result


def _text(value, label, maximum, single_line=True):
    if not isinstance(value, str):
        raise EnrichError(f"{label} 必须是字符串")
    cleaned = value.strip()
    if not cleaned:
        raise EnrichError(f"{label} 不能为空")
    if len(value) > maximum:
        raise EnrichError(f"{label} 超过长度上限 {maximum}")
    if single_line and ("\n" in value or "\r" in value):
        raise EnrichError(f"{label} 必须是单行字符串")
    return cleaned


def _text_array(value, label, maximum=MAX_TEXT):
    if not isinstance(value, list):
        raise EnrichError(f"{label} 必须是字符串数组")
    if len(value) > MAX_ITEMS:
        raise EnrichError(f"{label} 条数超过上限 {MAX_ITEMS}")
    return [_text(item, f"{label}[{i}]", maximum) for i, item in enumerate(value)]


def validate_proposal(proposal, vault=None):
    vault = os.path.realpath(vault or K.VAULT)
    if not isinstance(proposal, dict):
        raise EnrichError("proposal 顶层必须是 JSON 对象")
    if "page" not in proposal:
        raise EnrichError("proposal 缺少 page")
    page = load_page(proposal["page"], vault)
    summary = _text(proposal.get("summary"), "summary", MAX_SUMMARY)
    claims = proposal.get("claims")
    if not isinstance(claims, list) or not claims:
        raise EnrichError("claims 必须是非空数组；拒绝无证据 claims")
    if len(claims) > MAX_CLAIMS:
        raise EnrichError(f"claims 条数超过上限 {MAX_CLAIMS}")
    clean_claims = []
    cache = {}
    for i, claim in enumerate(claims):
        label = f"claims[{i}]"
        if not isinstance(claim, dict):
            raise EnrichError(f"{label} 必须是对象")
        text = _text(claim.get("text"), f"{label}.text", MAX_TEXT)
        evidence = claim.get("evidence")
        if not isinstance(evidence, dict):
            raise EnrichError(f"{label}.evidence 必须是对象；拒绝无证据 claim")
        for key in ("path", "line_start", "line_end", "quote"):
            if key not in evidence:
                raise EnrichError(f"{label}.evidence 缺少 {key}")
        rel, path = resolve_markdown(evidence["path"], vault)
        start, end = evidence["line_start"], evidence["line_end"]
        if type(start) is not int or type(end) is not int:
            raise EnrichError(f"{label}.evidence 行号必须是整数")
        if rel not in cache:
            cache[rel] = K.read_text(path).split("\n")
        lines = cache[rel]
        if start < 1 or end < start or end > len(lines):
            raise EnrichError(
                f"{label}.evidence 行号无效：{start}-{end}，文件共 {len(lines)} 行")
        quote = _text(evidence["quote"], f"{label}.evidence.quote", MAX_QUOTE,
                      single_line=False)
        quote = evidence["quote"]
        excerpt = "\n".join(lines[start - 1:end])
        if quote not in excerpt:
            raise EnrichError(f"{label}.evidence.quote 不在 {rel}:{start}-{end} 指定行内逐字存在")
        clean_claims.append({"text": text, "evidence": {
            "path": rel, "line_start": start, "line_end": end, "quote": quote}})
    clean = {"page": page["page"], "summary": summary, "claims": clean_claims}
    for key in ("limitations", "critical_assessment"):
        clean[key] = _text_array(proposal.get(key, []), key)
    clean["tags"] = _text_array(proposal.get("tags", []), "tags", 100)
    clean["links"] = _text_array(proposal.get("links", []), "links", 500)
    _reject_markers(clean)
    return clean, page


def render_section(proposal):
    lines = [START, HEADING, "", "### Summary", "", proposal["summary"], "",
             "### Claims", ""]
    for i, claim in enumerate(proposal["claims"], 1):
        ev = claim["evidence"]
        lines.extend([f"{i}. {claim['text']}",
                      f"   - Evidence: `{ev['path']}:{ev['line_start']}-{ev['line_end']}`",
                      "   - Quote:"])
        lines.extend("     > " + line for line in ev["quote"].split("\n"))
        lines.append("")
    for key, heading in (("limitations", "Limitations"),
                         ("critical_assessment", "Critical Assessment")):
        lines.extend([f"### {heading}", ""])
        values = proposal[key]
        lines.extend([f"- {value}" for value in values] if values else ["- 未提供。"])
        lines.append("")
    lines.extend(["### Links", ""])
    links = proposal["links"]
    if links:
        for link in links:
            rendered = link if link.startswith("[[") and link.endswith("]]") else f"[[{link}]]"
            lines.append(f"- {rendered}")
    else:
        lines.append("- 未提供。")
    lines.extend(["", END])
    return "\n".join(lines)


def replace_section(body, section):
    starts, ends = body.count(START), body.count(END)
    if starts != ends or starts > 1:
        raise EnrichError("现有 LLM 二次加工标记缺失、重复或不成对，拒绝覆盖正文")
    if starts == 1:
        start = body.index(START)
        end = body.index(END)
        if end < start:
            raise EnrichError("现有 LLM 二次加工标记顺序错误")
        end += len(END)
        return body[:start] + section + body[end:]
    headings = list(re.finditer(r"^##\s+LLM 二次加工\s*$", body, re.M))
    if len(headings) > 1:
        raise EnrichError("现有 LLM 二次加工标题重复，拒绝覆盖正文")
    if headings:
        match = headings[0]
        following = re.search(r"^##\s+", body[match.end():], re.M)
        end = match.end() + following.start() if following else len(body)
        return body[:match.start()] + section + "\n\n" + body[end:].lstrip("\n")
    prefix = body.rstrip()
    return (prefix + "\n\n" if prefix else "") + section + "\n"


def _fragment(key, value):
    rendered = lit_ingest.render_frontmatter({key: value}).split("\n")
    return "\n".join(rendered[1:-2])


def update_frontmatter(raw, changes):
    key_re = re.compile(r"^([A-Za-z_][\w\-]*)\s*:")
    for key in changes:
        matches = list(re.finditer(rf"^{re.escape(key)}\s*:", raw, re.M))
        if len(matches) > 1:
            raise EnrichError(f"frontmatter 键 {key} 重复，拒绝不安全改写")
    result = raw
    for key, value in changes.items():
        matches = list(re.finditer(r"^[A-Za-z_][\w\-]*\s*:", result, re.M))
        target = next((m for m in matches if m.group(0).split(":", 1)[0].strip() == key), None)
        fragment = _fragment(key, value)
        if target is None:
            result = result.rstrip("\n") + ("\n" if result.strip() else "") + fragment + "\n"
            continue
        end = len(result)
        for match in matches:
            if match.start() > target.start():
                end = match.start()
                break
        result = result[:target.start()] + fragment + "\n" + result[end:]
    return result.strip("\n")


def render_page(page, proposal, today=None):
    tags = _tag_list(page["fm"].get("tags"))
    tags = [tag for tag in tags if tag.strip() != "待精读"]
    for tag in proposal["tags"]:
        if tag not in tags:
            tags.append(tag)
    fm_raw = update_frontmatter(page["fm_raw"], {
        "summary": proposal["summary"],
        "updated": today or datetime.date.today().isoformat(),
        "tags": tags,
        "source_reliability": RELIABILITY,
    })
    body = replace_section(page["body"], render_section(proposal))
    text = K.join_frontmatter(fm_raw, body)
    check_raw, _ = K.split_frontmatter(text)
    check = K.parse_frontmatter(check_raw)
    if not check_raw.strip() or check.get("type") != "source":
        raise EnrichError("写前 frontmatter 复核失败")
    return text


def _restore_backup(backup, target):
    """写后断言失败时回滚；返回 (ok, detail)。"""
    try:
        import shutil
        shutil.copyfile(backup, target)
        return True, ""
    except OSError as exc:
        return False, str(exc)


def apply_proposal(proposal, vault=None, write=False, today=None):
    vault = os.path.realpath(vault or K.VAULT)
    clean, page = validate_proposal(proposal, vault)
    new_text = render_page(page, clean, today=today)
    changed = new_text != page["text"]
    result = {"ok": True, "page": clean["page"], "dry_run": not write,
              "changed": changed, "claims": len(clean["claims"]),
              "written": False, "backup": ""}
    if not write or not changed:
        return result
    backup = K.backup_file(page["path"], root=vault)
    if not backup:
        raise EnrichError("写前备份失败，拒绝写盘")
    result["backup"] = backup
    ok, detail = K.write_text_verified(page["path"], new_text, quiet=True,
                                       require_frontmatter=True)
    if not ok:
        restored, restore_detail = _restore_backup(backup, page["path"])
        suffix = ("已回滚" if restored else f"且自动回滚失败：{restore_detail}")
        raise EnrichError(f"写盘或写后复算失败：{detail}；{suffix}（备份：{backup}）")
    back_raw, _ = K.split_frontmatter(K.read_text(page["path"]))
    back = K.parse_frontmatter(back_raw)
    failure = ""
    if (not back_raw.strip() or back.get("type") != "source" or
            not str(back.get("summary") or "").strip()):
        failure = "frontmatter 不可读或 summary 为空"
    elif back.get("source_reliability") != RELIABILITY:
        failure = "source_reliability 不符合二次加工边界"
    elif "待精读" in _tag_list(back.get("tags")):
        failure = "tags 仍含待精读"
    if failure:
        restored, restore_detail = _restore_backup(backup, page["path"])
        suffix = ("已回滚" if restored else f"且自动回滚失败：{restore_detail}")
        raise EnrichError(f"写后断言失败：{failure}；{suffix}（备份：{backup}）")
    result["written"] = True
    return result


def load_proposal(path):
    try:
        with open(path, encoding="utf-8-sig") as handle:
            return json.load(handle)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise EnrichError(f"无法读取 proposal JSON：{exc}") from exc


def _print_json(payload):
    sys.stdout.write(json.dumps(payload, ensure_ascii=False, indent=2) + "\n")


def make_parser():
    parser = ArgumentParser(description="wiki source 的模型无关二次加工请求/应用工具")
    parser.add_argument("--selftest", action="store_true")
    sub = parser.add_subparsers(dest="command")
    request = sub.add_parser("request", help="生成结构化二次加工请求")
    request.add_argument("--page", required=True, help="相对 wiki/ 的 sources/X.md")
    request.add_argument("--json", action="store_true")
    apply_cmd = sub.add_parser("apply", help="校验 proposal；默认干跑")
    apply_cmd.add_argument("--proposal", required=True)
    apply_cmd.add_argument("--apply", action="store_true", help="真正写页；默认只干跑")
    apply_cmd.add_argument("--json", action="store_true")
    return parser


def selftest():
    failures = []

    def check(label, condition):
        print(f"  [{'ok' if condition else 'FAIL'}] {label}")
        if not condition:
            failures.append(label)

    def rejected(label, proposal, root, write=False):
        before = K.read_text(os.path.join(root, "wiki", "sources", "X.md"))
        try:
            apply_proposal(proposal, vault=root, write=write, today="2026-10-26")
        except EnrichError:
            after = K.read_text(os.path.join(root, "wiki", "sources", "X.md"))
            check(label, before == after)
        else:
            check(label, False)

    real_before = K.guard_state(wiki_glob=True)
    print("=== lit_enrich --selftest ===")
    with K.temp_dir(prefix="lit_enrich_") as root:
        page_path = os.path.join(root, "wiki", "sources", "X.md")
        raw_path = os.path.join(root, "raw", "text", "X.md")
        os.makedirs(os.path.dirname(page_path), exist_ok=True)
        os.makedirs(os.path.dirname(raw_path), exist_ok=True)
        raw_text = "标题\n实验温度 600 °C。\n结论仅适用于薄膜。\n"
        page_text = ("---\ntype: source\ncreated: 2026-01-01\nupdated: 2026-01-01\n"
                     "keep: untouched\nsummary: 旧摘要\ntags:\n  - source\n  - 待精读\n"
                     "source_reliability: 待核\nsources:\n  - \"[[raw/text/X.md]]\"\n---\n"
                     "# X\n\n原有正文。\n\n## 保留\n别动。\n")
        for path, text in ((page_path, page_text), (raw_path, raw_text)):
            with open(path, "w", encoding="utf-8", newline="\n") as handle:
                handle.write(text)
        proposal = {
            "page": "sources/X.md", "summary": "带证据的新摘要",
            "claims": [{"text": "实验使用 600 °C。",
                        "evidence": {"path": "raw/text/X.md", "line_start": 2,
                                     "line_end": 2, "quote": "实验温度 600 °C。"}}],
            "limitations": ["仅验证薄膜。"],
            "critical_assessment": ["尚需块体样品复核。"],
            "tags": ["enriched"], "links": ["concepts/示例"],
        }
        request = build_request("sources/X.md", root)
        check("request 含 page、raw 行范围、现有卡与 JSON 契约",
              request["page"] == "sources/X.md" and request["raw"][0]["line_end"] == 4
              and request["raw"][0]["content"] == raw_text
              and request["existing_card"]["frontmatter"]["keep"] == "untouched"
              and request["output_contract"]["schema"]["required"] ==
              ["page", "summary", "claims"])
        dry = apply_proposal(proposal, vault=root, today="2026-10-26")
        check("默认干跑通过且不改页", dry["dry_run"] and not dry["written"]
              and K.read_text(page_path) == page_text)
        applied = apply_proposal(proposal, vault=root, write=True, today="2026-10-26")
        enriched = K.read_text(page_path)
        fm_raw, body = K.split_frontmatter(enriched)
        fm = K.parse_frontmatter(fm_raw)
        check("正例写页、备份并保留其他 frontmatter/正文",
              applied["written"] and os.path.isfile(applied["backup"])
              and fm["keep"] == "untouched" and "别动。" in body
              and K.read_text(raw_path) == raw_text)
        check("更新 summary/updated/reliability 且移除待精读",
              fm["summary"] == "带证据的新摘要" and fm["updated"] == "2026-10-26"
              and fm["source_reliability"] == RELIABILITY
              and "待精读" not in fm["tags"] and "source" in fm["tags"]
              and "enriched" in fm["tags"])
        check("section 含全部约定内容",
              all(part in body for part in (HEADING, "### Summary", "### Claims",
                                            "### Limitations", "### Critical Assessment",
                                            "### Links", "raw/text/X.md:2-2",
                                            "实验温度 600 °C。", "仅验证薄膜。",
                                            "尚需块体样品复核。", "[[concepts/示例]]")))
        again = apply_proposal(proposal, vault=root, write=True, today="2026-10-26")
        check("幂等替换且相同提案不重复写盘",
              not again["written"] and K.read_text(page_path) == enriched
              and K.read_text(page_path).count(START) == 1
              and K.read_text(page_path).count(HEADING) == 1)
        bad_line = copy.deepcopy(proposal)
        bad_line["claims"][0]["evidence"]["line_end"] = 99
        rejected("错行号整体拒绝且不写页", bad_line, root, write=True)
        bad_quote = copy.deepcopy(proposal)
        bad_quote["claims"][0]["evidence"]["quote"] = "实验温度 900 °C。"
        rejected("错 quote 整体拒绝且不写页", bad_quote, root, write=True)
        traversal = copy.deepcopy(proposal)
        traversal["claims"][0]["evidence"]["path"] = "../outside.md"
        rejected("路径穿越整体拒绝且不写页", traversal, root, write=True)
        no_evidence = copy.deepcopy(proposal)
        no_evidence["claims"][0].pop("evidence")
        rejected("无证据 claim 被拒绝", no_evidence["claims"][0] and {
            "page": no_evidence["page"], "summary": no_evidence["summary"],
            "claims": no_evidence["claims"]}, root)
        empty_summary = copy.deepcopy(proposal)
        empty_summary["summary"] = "  "
        rejected("空 summary 被拒绝", empty_summary, root)
        bad_optional = copy.deepcopy(proposal)
        bad_optional["limitations"] = "不是数组"
        rejected("可选字段类型错误被拒绝", bad_optional, root)
        marker = copy.deepcopy(proposal)
        marker["summary"] = "正常摘要 " + START
        rejected("proposal 含 lit_enrich 标记文本被拒绝", marker, root, write=True)
        bad_tag = copy.deepcopy(proposal)
        bad_tag["tags"] = ["待精读"]
        rejected("写后断言失败时自动回滚（tags 含待精读）", bad_tag, root, write=True)
        # 历史页 tags 写成逗号标量时，也必须能识别并清掉「待精读」
        y_path = os.path.join(root, "wiki", "sources", "Y.md")
        y_text = ("---\ntype: source\ncreated: 2026-01-01\nupdated: 2026-01-01\n"
                  "summary: 旧摘要\ntags: source, 待精读\nsource_reliability: 待核\n"
                  "sources:\n  - \"[[raw/text/X.md]]\"\n---\n# Y\n\n正文。\n")
        with open(y_path, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(y_text)
        y_proposal = copy.deepcopy(proposal)
        y_proposal["page"] = "sources/Y.md"
        apply_proposal(y_proposal, vault=root, write=True, today="2026-10-26")
        y_fm = K.parse_frontmatter(K.split_frontmatter(K.read_text(y_path))[0])
        check("逗号标量 tags 被拆分且清掉待精读",
              "待精读" not in _tag_list(y_fm.get("tags"))
              and "source" in _tag_list(y_fm.get("tags")))
    check("selftest 未改真实 wiki", not K.guard_diff(real_before, K.guard_state(wiki_glob=True)))
    print(f"=== selftest {'PASS' if not failures else 'FAIL'}: {len(failures)} failure(s) ===")
    return 0 if not failures else 1


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    wants_json = "--json" in argv or (argv and argv[0] == "request")
    try:
        args = make_parser().parse_args(argv)
    except UsageError as exc:
        if wants_json:
            _print_json({"ok": False, "error": {"type": "arguments", "message": str(exc)}})
        else:
            print(f"参数错误：{exc}", file=sys.stderr)
        return 2
    if args.selftest:
        return selftest()
    if not args.command:
        if wants_json:
            _print_json({"ok": False, "error": {"type": "arguments",
                                               "message": "缺少 request 或 apply 子命令"}})
        else:
            make_parser().print_help(sys.stderr)
        return 2
    try:
        if args.command == "request":
            payload = build_request(args.page)
            _print_json(payload)
            return 0
        proposal = load_proposal(args.proposal)
        result = apply_proposal(proposal, write=args.apply)
        if args.json:
            _print_json(result)
        else:
            mode = "已写入" if result["written"] else ("干跑通过" if result["dry_run"] else "无需写入")
            print(f"[ok] {mode}：{result['page']}；claims={result['claims']}；"
                  f"changed={str(result['changed']).lower()}")
        return 0
    except EnrichError as exc:
        if wants_json or getattr(args, "json", False):
            _print_json({"ok": False, "error": {"type": "validation", "message": str(exc)}})
        else:
            print(f"[lit_enrich] {exc}", file=sys.stderr)
        return 1
    except (OSError, UnicodeError, ValueError, TypeError) as exc:
        if wants_json or getattr(args, "json", False):
            _print_json({"ok": False, "error": {"type": "io", "message": str(exc)}})
        else:
            print(f"[lit_enrich] {type(exc).__name__}: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
